html:
{#- The warranty certificate (SP-80): the station's components, each with its warranty from the
    operation date. The text is the admin's Warranty Certificate template. -#}
{% extends "smart_power/templates/print/base_rtl.html" %}
{%- set w = warranty_print(doc) -%}
{% block title %}
<table class="sp-quote-head">
	<tr>
		<td>
			<h2>{{ _("Warranty Certificate") }}</h2>
			<div>{{ _("Station") }}: <span class="sp-num">{{ doc.name }}</span></div>
		</td>
		<td class="sp-quote-meta"><div>{{ _("Operation Date") }}: {{ w.operation_date }}</div></td>
	</tr>
	<tr>
		<td>{{ _("Customer") }}: <strong>{{ doc.customer_name or doc.customer or "" }}</strong></td>
		<td class="sp-quote-meta">{%- if doc.location_text %}<div>{{ _("Site") }}: {{ doc.location_text }}</div>{% endif %}</td>
	</tr>
</table>
{% endblock %}
{% block body %}
{{ sp_block("Warranty Certificate", "preamble", doc) }}
<table class="sp-table sp-warranty-components">
	<thead>
		<tr><th>#</th><th>{{ _("Component") }}</th><th>{{ _("Item") }}</th><th>{{ _("Serial No.") }}</th><th>{{ _("Warranty (months)") }}</th><th>{{ _("Warranty Ends") }}</th></tr>
	</thead>
	<tbody>
	{%- for c in w.components %}
		<tr>
			<td class="sp-num">{{ loop.index }}</td>
			<td>{{ _(c.component_type) if c.component_type else "" }}</td>
			<td>{{ c.item_name or "" }}</td>
			<td class="sp-num">{{ c.serial or "" }}</td>
			<td class="sp-num">{{ c.warranty_months or "" }}</td>
			<td>{{ c.warranty_end_ar }}</td>
		</tr>
	{%- endfor %}
	</tbody>
</table>
{%- for block in sp_blocks("Warranty Certificate", doc, ["preamble"]) %}{{ block }}{% endfor %}
{% endblock %}
{% block signatures %}
{{ signature_block(_("The customer"), _("For Smart Power")) }}
{%- if w.stamp %}<div class="sp-stamp"><img src="{{ w.stamp }}" alt=""></div>{% endif %}
{% endblock %}
